insert into public.articles (id, sport_id, region_id, city_id, title_ar, title_en, slug, summary_ar, body_ar, status, published_at) values
('a0000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001','دوري أحياء الرياض يدخل أسبوع الحسم','Riyadh neighborhood league enters decisive week','riyadh-neighborhood-league-2026-week','بيانات تجريبية: منافسة قوية في صدارة دوري أحياء الرياض.','هذه مقالة تجريبية لعرض نظام الأخبار في منصة الرياضة المحلية. جميع الأسماء والبيانات خيالية ومخصصة للاختبار فقط.','published','2026-07-30 09:00:00+03'),
('a0000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','ملاعب جدة تفتح حجوزات نهاية الأسبوع','Jeddah venues open weekend bookings','jeddah-venues-weekend-bookings','بيانات تجريبية: توفر أوقات جديدة للحجز في جدة.','محتوى تجريبي يوضح ربط المقالات بالمناطق والمدن والرياضات داخل المنصة.','published','2026-07-29 16:00:00+03');
